mapper.select:
SELECT u.user_sq AS userSq, u.user_type_cd AS userTypeCd, u.user_id AS userId, CASE WHEN f.file_save_nm IS NOT NULL THEN CONCAT('/api/files/', f.file_save_nm) ELSE NULL END AS profileImageUrl, u.user_nm AS userNm, COALESCE(c.company_nm, c2.company_nm) AS companyNm, u.user_email AS userEmail, u.user_phone_num AS userPhoneNum, u.user_gender_cd AS userGenderCd, u.user_created_at_dtm AS userCreatedDtm, u.user_modified_at_dtm AS userModifiedDtm, u.user_is_deleted_yn AS userIsDeletedYn, u.user_signup_type_cd AS userSignupTypeCd, u.user_is_activate_yn AS userIsActivateYn, u.user_agreed_privacy_policy_yn AS userAgreedPrivacyPolicyYn FROM TBL_USER_M u LEFT JOIN TBL_COMPANY_S c ON c.user_sq = u.user_sq LEFT JOIN TBL_COMPANY_MEMBER_R cm ON cm.user_sq = u.user_sq AND cm.company_member_status_cd = 401 LEFT JOIN TBL_COMPANY_S c2 ON c2.company_sq = cm.company_sq LEFT JOIN TBL_USER_PROFILE_IMAGE_S up ON up.user_sq = u.user_sq LEFT JOIN TBL_COMMON_FILE_S f ON f.file_sq = up.file_sq WHERE 1=1
AND u.user_type_cd IN #{t}
AND (u.user_nm LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY
u.user_type_cd u.user_id up.file_sq u.user_nm COALESCE(c.company_nm, c2.company_nm) u.user_email u.user_phone_num u.user_gender_cd u.user_created_at_dtm u.user_modified_at_dtm u.user_is_deleted_yn u.user_signup_type_cd u.user_is_activate_yn u.user_agreed_privacy_policy_yn u.user_sq
${sortOrder} LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM TBL_USER_M u LEFT JOIN TBL_COMPANY_S c ON c.user_sq = u.user_sq LEFT JOIN TBL_COMPANY_MEMBER_R cm ON cm.user_sq = u.user_sq AND cm.company_member_status_cd = 401 LEFT JOIN TBL_USER_PROFILE_IMAGE_S up ON up.user_sq = u.user_sq WHERE 1=1
AND u.user_type_cd IN #{t}
AND (u.user_nm LIKE CONCAT('%', #{keyword}, '%'))

mapper.update:
UPDATE
	TBL_COMMON_FILE_S
SET
	file_save_nm = #{savedNm}
WHERE
	file_sq = #{fileSq}

  		UPDATE
  			TBL_COMPANY_S c
  		INNER JOIN (
			SELECT company_sq FROM TBL_COMPANY_S WHERE user_sq = #{userSq}
			UNION
			SELECT company_sq FROM TBL_COMPANY_MEMBER_R
			WHERE user_sq = #{userSq} AND company_member_status_cd = 401
		) target ON c.company_sq = target.company_sq
  		SET
  			c.company_nm = #{companyNm}
